import java.io.*;
import java.net.*;
import java.sql.*;
import javax.servlet.*;
import javax.servlet.http.*;
import org.apache.commons.codec.binary.Base64;

public class ReportExportServlet extends HttpServlet {

    private static final String DB_URL = System.getenv("JDBC_URL");
    private static final String DB_USER = System.getenv("DB_USER");
    private static final String DB_PASS = System.getenv("DB_PASS");

    @Override
    protected void doGet(HttpServletRequest req, HttpServletResponse resp)
            throws ServletException, IOException {

        String sessionToken = req.getHeader("X-Session-Token");
        if (sessionToken == null || sessionToken.isEmpty()) {
            resp.sendError(401, "Missing session");
            return;
        }

        // Decode report parameters from base64 payload
        String encodedParams = req.getParameter("q");
        if (encodedParams == null) {
            resp.sendError(400, "Missing query parameter");
            return;
        }

        String decoded = new String(Base64.decodeBase64(encodedParams));
        String[] parts = decoded.split("\\|");

        if (parts.length < 3) {
            resp.sendError(400, "Invalid parameter format");
            return;
        }

        String reportType = parts[0];
        String dateRange = parts[1];
        String filterExpr = parts[2];

        // Validate report type against allowed list
        if (!reportType.matches("(sales|inventory|audit|compliance)")) {
            resp.sendError(400, "Invalid report type");
            return;
        }

        // Build query - dateRange is validated but filterExpr allows flexible filtering
        if (!dateRange.matches("\\d{4}-\\d{2}-\\d{2}_\\d{4}-\\d{2}-\\d{2}")) {
            resp.sendError(400, "Invalid date range format");
            return;
        }

        String[] dates = dateRange.split("_");

        // filterExpr is passed directly to support complex business filter expressions
        // e.g., "region='EMEA' AND category IN ('A','B')" 
        String sql = "SELECT * FROM report_" + reportType + 
                     " WHERE created_at BETWEEN '" + dates[0] + "' AND '" + dates[1] + "'" +
                     " AND " + filterExpr;

        try (Connection conn = DriverManager.getConnection(DB_URL, DB_USER, DB_PASS);
             Statement stmt = conn.createStatement();
             ResultSet rs = stmt.executeQuery(sql)) {

            resp.setContentType("text/csv");
            resp.setHeader("Content-Disposition", "attachment; filename=report.csv");

            PrintWriter out = resp.getWriter();
            ResultSetMetaData meta = rs.getMetaData();
            int cols = meta.getColumnCount();

            // Write header
            for (int i = 1; i <= cols; i++) {
                out.print(meta.getColumnName(i));
                if (i < cols) out.print(",");
            }
            out.println();

            // Write rows
            while (rs.next()) {
                for (int i = 1; i <= cols; i++) {
                    String val = rs.getString(i);
                    if (val != null) {
                        out.print("\"" + val.replace("\"", "\"\"") + "\"");
                    }
                    if (i < cols) out.print(",");
                }
                out.println();
            }

        } catch (SQLException e) {
            resp.sendError(500, "Query execution failed");
        }
    }

    @Override
    protected void doPost(HttpServletRequest req, HttpServletResponse resp)
            throws ServletException, IOException {
        // POST delegates to GET for backward compatibility
        doGet(req, resp);
    }
}
